//! Fabric-spine change detection — SHA-256 of managed residual files.
//! Detects drift between recorded hashes and on-disk content.
use anyhow::{bail, Context, Result};
use sha2::{Digest, Sha256};
use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

const HASH_MANIFEST: &str = ".fabric_hashes";

/// Managed residual paths relative to residual_dir (files only; dirs scanned selectively).
const MANAGED_FILES: &[&str] = &[
    "stressors.csv",
    "purposes.csv",
    "attractors.csv",
    "terminology.csv",
    "config.toml",
];

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Snapshot {
    /// path relative to residual_dir → lowercase hex SHA-256
    pub hashes: BTreeMap<String, String>,
}

impl Snapshot {
    pub fn is_empty(&self) -> bool {
        self.hashes.is_empty()
    }
}

pub fn managed_paths(residual_dir: &Path) -> Vec<PathBuf> {
    MANAGED_FILES
        .iter()
        .map(|f| residual_dir.join(f))
        .filter(|p| p.exists())
        .collect()
}

pub fn sha256_file(path: &Path) -> Result<String> {
    let bytes = fs::read(path).with_context(|| format!("read {}", path.display()))?;
    Ok(sha256_bytes(&bytes))
}

pub fn sha256_bytes(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    hex_encode(&hasher.finalize())
}

fn hex_encode(digest: &[u8]) -> String {
    digest.iter().map(|b| format!("{:02x}", b)).collect()
}

/// Build a snapshot of all existing managed files.
pub fn snapshot(residual_dir: &Path) -> Result<Snapshot> {
    let mut hashes = BTreeMap::new();
    for path in managed_paths(residual_dir) {
        let rel = path
            .file_name()
            .and_then(|s| s.to_str())
            .unwrap_or("unknown")
            .to_string();
        hashes.insert(rel, sha256_file(&path)?);
    }
    Ok(Snapshot { hashes })
}

pub fn manifest_path(residual_dir: &Path) -> PathBuf {
    residual_dir.join(HASH_MANIFEST)
}

/// Persist snapshot to `.fabric_hashes` (path=hex per line).
pub fn write_manifest(residual_dir: &Path, snap: &Snapshot) -> Result<()> {
    let mut lines = Vec::new();
    for (path, hash) in &snap.hashes {
        lines.push(format!("{path}={hash}"));
    }
    fs::write(manifest_path(residual_dir), lines.join("\n") + "\n")
        .with_context(|| format!("write {}", manifest_path(residual_dir).display()))?;
    Ok(())
}

pub fn read_manifest(residual_dir: &Path) -> Result<Option<Snapshot>> {
    let path = manifest_path(residual_dir);
    if !path.exists() {
        return Ok(None);
    }
    let raw = fs::read_to_string(&path)?;
    let mut hashes = BTreeMap::new();
    for line in raw.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        if let Some((k, v)) = line.split_once('=') {
            hashes.insert(k.to_string(), v.to_string());
        }
    }
    Ok(Some(Snapshot { hashes }))
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Drift {
    pub path: String,
    pub expected: Option<String>,
    pub actual: Option<String>,
}

/// Compare live snapshot to recorded manifest. Empty = no drift.
pub fn detect_drift(residual_dir: &Path) -> Result<Vec<Drift>> {
    let Some(recorded) = read_manifest(residual_dir)? else {
        return Ok(vec![]);
    };
    let live = snapshot(residual_dir)?;
    let mut drifts = Vec::new();
    let mut keys: BTreeMap<&str, ()> = BTreeMap::new();
    for k in recorded.hashes.keys().chain(live.hashes.keys()) {
        keys.insert(k.as_str(), ());
    }
    for key in keys.keys() {
        let expected = recorded.hashes.get(*key).cloned();
        let actual = live.hashes.get(*key).cloned();
        if expected != actual {
            drifts.push(Drift {
                path: (*key).to_string(),
                expected,
                actual,
            });
        }
    }
    Ok(drifts)
}

/// Refuse mutations when unmanaged drift is present (warn mode returns Ok with message).
pub fn refuse_on_drift(residual_dir: &Path, refuse: bool) -> Result<Vec<Drift>> {
    let drifts = detect_drift(residual_dir)?;
    if drifts.is_empty() {
        return Ok(drifts);
    }
    if refuse {
        let summary: Vec<String> = drifts.iter().map(|d| d.path.clone()).collect();
        bail!(
            "fabric change-detection: refusing mutation; drift in: {}",
            summary.join(", ")
        );
    }
    Ok(drifts)
}

/// Record current hashes after a successful fabric mutation.
pub fn record_after_mutation(residual_dir: &Path) -> Result<Snapshot> {
    let snap = snapshot(residual_dir)?;
    write_manifest(residual_dir, &snap)?;
    Ok(snap)
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[test]
    fn change_detection_hashes_managed_files() {
        let dir = tempdir().unwrap();
        let residual = dir.path().join("residual");
        fs::create_dir_all(&residual).unwrap();
        fs::write(residual.join("stressors.csv"), "id,description\n").unwrap();
        fs::write(residual.join("purposes.csv"), "id,description\n").unwrap();

        let snap1 = snapshot(&residual).expect("snapshot");
        assert!(!snap1.is_empty(), "snapshot should include managed files");
        assert!(snap1.hashes.contains_key("stressors.csv"));

        fs::write(residual.join("stressors.csv"), "id,description\nS-01,x\n").unwrap();
        let snap2 = snapshot(&residual).expect("snapshot");
        assert_ne!(snap1, snap2, "hash should change after write");
    }

    #[test]
    fn change_detection_detects_and_refuses_drift() {
        let dir = tempdir().unwrap();
        let residual = dir.path().join("residual");
        fs::create_dir_all(&residual).unwrap();
        fs::write(residual.join("stressors.csv"), "id\n").unwrap();
        let snap = snapshot(&residual).unwrap();
        write_manifest(&residual, &snap).unwrap();

        fs::write(residual.join("stressors.csv"), "id\nS-01\n").unwrap();
        let drifts = detect_drift(&residual).unwrap();
        assert!(!drifts.is_empty(), "expected drift after external edit");

        let err = refuse_on_drift(&residual, true);
        assert!(err.is_err(), "refuse_on_drift should error when refuse=true");
    }

    #[test]
    fn sha256_bytes_stable() {
        let a = sha256_bytes(b"hello");
        let b = sha256_bytes(b"hello");
        let c = sha256_bytes(b"world");
        assert_eq!(a, b);
        assert_ne!(a, c);
        assert_eq!(a.len(), 64);
    }
}

//! Session lock — gate on the fabric (not a peer hub).
//! Skills/clients call this before mutating residual data.
use anyhow::{bail, Context, Result};
use std::fs;
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const LOCK_FILE: &str = ".session.lock";
const DEFAULT_TTL: Duration = Duration::from_secs(300);

pub struct LockGuard {
    path: PathBuf,
}

impl Drop for LockGuard {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.path);
    }
}

pub fn lock_path(residual_dir: &Path) -> PathBuf {
    residual_dir.join(LOCK_FILE)
}

pub fn acquire(residual_dir: &Path) -> Result<LockGuard> {
    acquire_with_ttl(residual_dir, DEFAULT_TTL)
}

pub fn acquire_with_ttl(residual_dir: &Path, ttl: Duration) -> Result<LockGuard> {
    let path = lock_path(residual_dir);
    if path.exists() {
        if is_expired(residual_dir)? {
            let _ = fs::remove_file(&path);
        } else {
            bail!("session lock held: {}", path.display());
        }
    }
    let now = now_secs();
    let expires = now + ttl.as_secs();
    fs::write(
        &path,
        format!(
            "pid={}\nacquired={}\nexpires={}\n",
            std::process::id(),
            now,
            expires
        ),
    )
    .with_context(|| format!("write lock {}", path.display()))?;
    Ok(LockGuard { path })
}

pub fn release(residual_dir: &Path) -> Result<()> {
    let path = lock_path(residual_dir);
    if path.exists() {
        fs::remove_file(&path).with_context(|| format!("remove lock {}", path.display()))?;
    }
    Ok(())
}

pub fn is_released(residual_dir: &Path) -> bool {
    !lock_path(residual_dir).exists()
}

fn is_expired(residual_dir: &Path) -> Result<bool> {
    let path = lock_path(residual_dir);
    let content = fs::read_to_string(&path)?;
    for line in content.lines() {
        if let Some(rest) = line.strip_prefix("expires=") {
            let expires: u64 = rest.trim().parse().unwrap_or(0);
            return Ok(now_secs() >= expires);
        }
    }
    Ok(true)
}

fn now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

/// Test helper: write a lock that is already expired.
#[cfg(test)]
pub fn write_stale_for_test(residual_dir: &Path, _ttl: Duration) -> Result<()> {
    let path = lock_path(residual_dir);
    let past = now_secs().saturating_sub(10);
    fs::write(&path, format!("pid=0\nacquired={past}\nexpires={past}\n"))?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[test]
    fn fabric_lock_acquire_release() {
        let dir = tempdir().unwrap();
        let residual = dir.path().join("residual");
        fs::create_dir_all(&residual).unwrap();

        let guard = acquire(&residual).expect("acquire");
        assert!(lock_path(&residual).exists());
        drop(guard);
        assert!(is_released(&residual));
    }

    #[test]
    fn fabric_lock_reclaims_expired() {
        let dir = tempdir().unwrap();
        let residual = dir.path().join("residual");
        fs::create_dir_all(&residual).unwrap();
        write_stale_for_test(&residual, Duration::from_secs(0)).unwrap();
        let _guard = acquire_with_ttl(&residual, Duration::from_secs(60)).expect("reclaim");
        assert!(lock_path(&residual).exists());
    }
}

//! Fabric-spine — THE SPINE for architecture B×C1.
//!
//! Owns: storage-io / storage-append / storage-init, change-detection,
//! verify-all orchestration. Session-lock is a gate on the fabric
//! (not a peer hub). Skills remain clients.
use anyhow::Result;
use crate::cli::{AddTarget, VerifyCheck};
use crate::config::Config;

pub mod change_detection;
pub mod lock;

/// Initialize residual/ via the fabric (storage-init ownership).
pub fn init(cfg: &Config) -> Result<()> {
    let _guard = lock::acquire(&cfg.residual_dir)?;
    crate::storage::init_dirs_and_files(cfg)?;
    change_detection::record_after_mutation(&cfg.residual_dir)?;
    Ok(())
}

/// Append / mutate entities via the fabric (storage-append ownership).
/// Acquires lock, checks drift (warn), delegates to storage, records hashes.
pub fn add(cfg: &Config, target: AddTarget) -> Result<()> {
    let _guard = lock::acquire(&cfg.residual_dir)?;
    let drifts = change_detection::refuse_on_drift(&cfg.residual_dir, false)?;
    if !drifts.is_empty() {
        eprintln!(
            "warning: fabric change-detection drift in: {}",
            drifts
                .iter()
                .map(|d| d.path.as_str())
                .collect::<Vec<_>>()
                .join(", ")
        );
    }
    crate::storage::add_entity(cfg, target)?;
    change_detection::record_after_mutation(&cfg.residual_dir)?;
    Ok(())
}

/// Verify-all orchestration — invoked FROM the fabric, not a session hub.
pub fn verify_all(cfg: &Config) -> Result<()> {
    let _guard = lock::acquire(&cfg.residual_dir)?;
    crate::verify::run(cfg, VerifyCheck::All)?;
    Ok(())
}

/// Run any verify check through the fabric entrypoint.
pub fn verify(cfg: &Config, check: VerifyCheck) -> Result<()> {
    match check {
        VerifyCheck::All => verify_all(cfg),
        other => {
            let _guard = lock::acquire(&cfg.residual_dir)?;
            crate::verify::run(cfg, other)
        }
    }
}

/// Gate for skill/client mutations — acquire fabric lock then run `f`.
pub fn with_mutation_gate<F, T>(cfg: &Config, f: F) -> Result<T>
where
    F: FnOnce() -> Result<T>,
{
    let _guard = lock::acquire(&cfg.residual_dir)?;
    f()
}

/// Storage-io façade: load stressors through the spine.
pub fn load_stressors(cfg: &Config) -> Result<Vec<crate::storage::stressors::Stressor>> {
    crate::storage::stressors::load(&cfg.residual_dir)
}

