//! Evidence fuse (C1) — owns research + personas as one evidence surface.
pub mod personas;
pub mod research;

use anyhow::Result;
use std::path::Path;

/// Unified evidence listing for skill/context consumers.
#[derive(Debug, Default)]
pub struct EvidenceBundle {
    pub persona_names: Vec<String>,
    pub research_sources: Vec<String>,
}

pub fn load_bundle(residual_dir: &Path) -> Result<EvidenceBundle> {
    let persona_names = personas::list_names(residual_dir)?;
    let research_sources = list_research_sources(residual_dir)?;
    Ok(EvidenceBundle {
        persona_names,
        research_sources,
    })
}

fn list_research_sources(residual_dir: &Path) -> Result<Vec<String>> {
    let dir = residual_dir.join("research");
    if !dir.exists() {
        return Ok(vec![]);
    }
    let mut names = Vec::new();
    for entry in std::fs::read_dir(&dir)? {
        let entry = entry?;
        let path = entry.path();
        if path.extension().and_then(|e| e.to_str()) == Some("md") {
            if let Some(stem) = path.file_stem().and_then(|s| s.to_str()) {
                names.push(stem.to_string());
            }
        }
    }
    names.sort();
    Ok(names)
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[test]
    fn evidence_unifies_personas_and_research() {
        let dir = tempdir().unwrap();
        let residual = dir.path();
        std::fs::create_dir_all(residual.join("personas")).unwrap();
        std::fs::create_dir_all(residual.join("research")).unwrap();

        personas::create(
            residual,
            personas::Persona {
                name: "architect".into(),
                role: "architect".into(),
                concerns: "coupling".into(),
                desires: "clarity".into(),
                stressor_ids: vec![],
            },
        )
        .unwrap();
        research::save(residual, "nkp-notes", "# notes\n").unwrap();

        let bundle = load_bundle(residual).unwrap();
        assert!(bundle.persona_names.iter().any(|n| n == "architect"));
        assert!(bundle.research_sources.iter().any(|n| n == "nkp-notes"));
    }
}

//! Lexicon — terminology + trait parsing/validation helpers.
pub mod terminology;
pub mod traits;

pub use terminology::{append, load, term_set, Term};
pub use traits::{parse_trait, trait_uses_terminology, TraitParts};

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;
    use tempfile::tempdir;

    #[test]
    fn lexicon_owns_terminology_and_traits() {
        let dir = tempdir().unwrap();
        append(
            dir.path(),
            Term {
                term: "attractor".into(),
                definition: "desired state".into(),
                domain: "nkp".into(),
                related_terms: "".into(),
            },
        )
        .unwrap();
        let terms = load(dir.path()).unwrap();
        let set = term_set(&terms);
        assert!(set.contains("attractor"));

        let parts = parse_trait("system reaches attractor state").unwrap();
        assert!(trait_uses_terminology(&parts, &set));

        let mut empty = HashSet::new();
        empty.insert("other".into());
        assert!(!trait_uses_terminology(&parts, &empty));
    }
}

//! Trait parsing — subject verb predicate against terminology.
use std::collections::HashSet;

#[derive(Debug, Clone)]
pub struct TraitParts {
    pub subject: String,
    pub verb: String,
    pub predicates: Vec<String>,
}

/// Parse a trait string into (subject, verb, predicates).
/// Format: "<subject> <verb> <pred1> [<pred2>...]"
/// Returns None if fewer than 3 words.
pub fn parse_trait(trait_str: &str) -> Option<TraitParts> {
